import random

from txn_simulator import Workload
from workloads import WORKLOAD_1, WORKLOAD_2, WORKLOAD_3

# EVOLVE-BLOCK-START

def get_best_schedule(workload, num_seqs):
    """
    Conflict-graph DAG critical-path seeding + multi-restart exact-cost
    greedy + hybrid local search (2-opt swaps, or-opt reinsertions,
    segment reversals) + iterated local search with a diverse pool.

    1. Build the transaction conflict graph (edge = shared data key,
       weight = number of shared keys). Compute a criticality score per
       transaction via longest-path relaxation (Graham/Hu-style list
       scheduling priority): transactions on long downstream conflict
       chains are scheduled first.
    2. Construct seeds with a criticality-guided builder: at each step,
       consider the top few remaining transactions by criticality and
       append the one with the lowest TRUE makespan
       (workload.get_opt_seq_cost). Also run plain multi-start greedy.
    3. First-improvement local search with swaps, reinsertions, reversals.
    4. Perturb-and-repolish seeded from a pool of local optima until the
       time budget expires.
    """
    import time

    time_budget = 110.0
    start_time = time.time()
    n = workload.num_txns

    # ---------- conflict graph + critical-path priorities ----------
    def txn_keys(t):
        """Extract the set of data keys of transaction index t."""
        for attr in ("txns", "transactions", "txn_list"):
            data = getattr(workload, attr, None)
            if data is None:
                continue
            item = data[t] if isinstance(data, (list, tuple)) else data.get("txn%d" % t)
            if item is None and isinstance(data, dict):
                for k in (t, str(t), "txn%d" % t):
                    if k in data:
                        item = data[k]
                        break
            if item is None:
                continue
            keys = set()
            if isinstance(item, str):
                toks = item.split()
            elif isinstance(item, (list, tuple)):
                toks = [str(x) for x in item]
            else:
                toks = []
            for tok in toks:
                parts = tok.split("-")
                if len(parts) == 2:
                    keys.add(parts[1])
            if keys or toks:
                return keys
        return set()

    keys_of = {}
    key_map = {}
    for t in range(n):
        ks = txn_keys(t)
        keys_of[t] = ks
        for k in ks:
            key_map.setdefault(k, set()).add(t)

    # adjacency with weights = number of shared keys
    adj = {t: {} for t in range(n)}
    for k, ts in key_map.items():
        ts = sorted(ts)
        for i in range(len(ts)):
            for j in range(i + 1, len(ts)):
                a, b = ts[i], ts[j]
                adj[a][b] = adj[a].get(b, 0) + 1
                adj[b][a] = adj[b].get(a, 0) + 1

    # longest-path criticality: crit[t] = longest weighted path from t
    # to any sink in the (heuristic, undirected-as-DAG) conflict graph.
    crit = {t: 0.0 for t in range(n)}
    for _ in range(n):
        changed = False
        for t in range(n):
            best = 0.0
            for u, w in adj[t].items():
                cand = crit[u] + w
                if cand > best:
                    best = cand
            if best > crit[t]:
                crit[t] = best
                changed = True
        if not changed:
            break
    degree = {t: sum(adj[t].values()) for t in range(n)}

    def critical_path_seed(topk=4):
        """Graham-style list scheduling: repeatedly append the true-cost
        best transaction among the topk most critical remaining ones."""
        remaining = list(range(n))
        seq = []
        while remaining:
            remaining.sort(key=lambda t: (-crit[t], -degree[t], t))
            cands = remaining[:topk]
            best_c, best_t = None, None
            for t in cands:
                c = workload.get_opt_seq_cost(seq + [t])
                if best_c is None or c < best_c:
                    best_c, best_t = c, t
            seq.append(best_t)
            remaining.remove(best_t)
        return workload.get_opt_seq_cost(seq), seq

    def greedy(start_txn, noise=0.0):
        seq = [start_txn]
        remaining = [x for x in range(n) if x != start_txn]
        while remaining:
            scored = []
            for t in remaining:
                c = workload.get_opt_seq_cost(seq + [t])
                scored.append((c, random.random() if noise else t, t))
            scored.sort()
            pick = scored[0][2]
            if noise and len(scored) > 1 and random.random() < noise:
                pick = scored[1][2]
            seq.append(pick)
            remaining.remove(pick)
        return workload.get_opt_seq_cost(seq), seq

    def local_search(seq, cost):
        improved = True
        while improved and time.time() - start_time < time_budget:
            improved = False
            # 2-opt swaps
            for i in range(n - 1):
                for j in range(i + 1, n):
                    if time.time() - start_time >= time_budget:
                        return cost, seq
                    seq[i], seq[j] = seq[j], seq[i]
                    c = workload.get_opt_seq_cost(seq)
                    if c < cost:
                        cost = c
                        improved = True
                    else:
                        seq[i], seq[j] = seq[j], seq[i]
            # or-opt: move a single txn to another position
            for i in range(n):
                if time.time() - start_time >= time_budget:
                    return cost, seq
                t = seq.pop(i)
                for j in range(n):
                    if j == i:
                        continue
                    seq.insert(j, t)
                    c = workload.get_opt_seq_cost(seq)
                    if c < cost:
                        cost = c
                        improved = True
                        break
                    seq.pop(j)
                else:
                    seq.insert(i, t)
            # segment reversal: reverse block [i..j]
            for i in range(n - 1):
                for j in range(i + 2, n):
                    if time.time() - start_time >= time_budget:
                        return cost, seq
                    seq[i:j + 1] = seq[i:j + 1][::-1]
                    c = workload.get_opt_seq_cost(seq)
                    if c < cost:
                        cost = c
                        improved = True
                    else:
                        seq[i:j + 1] = seq[i:j + 1][::-1]
        return cost, seq

    best_cost = None
    best_seq = None

    # Critical-path guided seeds (breakthrough heuristic)
    try:
        for k in (3, 6, 10):
            if time.time() - start_time >= time_budget * 0.35:
                break
            c, seq = critical_path_seed(topk=k)
            if best_cost is None or c < best_cost:
                best_cost, best_seq = c, seq
    except Exception:
        pass

    starts = list(range(n))
    if n > 12:
        step = max(1, n // 12)
        starts = list(range(0, n, step))[:12]

    for s in starts:
        if time.time() - start_time >= time_budget * 0.5:
            break
        c, seq = greedy(s)
        if best_cost is None or c < best_cost:
            best_cost, best_seq = c, seq

    while time.time() - start_time < time_budget * 0.45:
        s = random.randint(0, n - 1)
        c, seq = greedy(s, noise=0.15)
        if best_cost is None or c < best_cost:
            best_cost, best_seq = c, seq

    best_cost, best_seq = local_search(best_seq, best_cost)

    pool = [(best_cost, best_seq)]

    while time.time() - start_time < time_budget:
        if random.random() < 0.5:
            base = best_seq
        else:
            base = random.choice(pool)[1]
        cand = base[:]
        if random.random() < 0.5:
            for _ in range(2):
                i, j = random.sample(range(n), 2)
                cand[i], cand[j] = cand[j], cand[i]
        else:
            i, j = sorted(random.sample(range(n), 2))
            cand[i:j + 1] = cand[i:j + 1][::-1]
        c, cand = local_search(cand, workload.get_opt_seq_cost(cand))
        if c < best_cost:
            best_cost, best_seq = c, cand
        if len(pool) < 5 or c < pool[-1][0]:
            pool.append((c, cand))
            pool.sort(key=lambda x: x[0])
            pool = pool[:5]

    assert len(set(best_seq)) == workload.num_txns
    return best_cost, best_seq

# EVOLVE-BLOCK-END

def get_random_costs():
    workload_size = 100
    workload = Workload(WORKLOAD_1)

    makespan1, schedule1 = get_best_schedule(workload, 10)
    cost1 = workload.get_opt_seq_cost(schedule1)

    workload2 = Workload(WORKLOAD_2)
    makespan2, schedule2 = get_best_schedule(workload2, 10)
    cost2 = workload2.get_opt_seq_cost(schedule2)

    workload3 = Workload(WORKLOAD_3)
    makespan3, schedule3 = get_best_schedule(workload3, 10)
    cost3 = workload3.get_opt_seq_cost(schedule3)
    print(cost1, cost2, cost3)
    return cost1 + cost2 + cost3, [schedule1, schedule2, schedule3]


if __name__ == "__main__":
    makespan, schedule = get_random_costs()
    print(f"Makespan: {makespan}")
